body.script:
function switchAuthTab(tab) {
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
  document.querySelectorAll('.tab-panel').forEach(p => p.classList.toggle('active', p.id === 'tab-' + tab));
}
function switchServerTab(tab) {
  document.querySelectorAll('.stab').forEach(b => b.classList.toggle('active', b.dataset.stab === tab));
  document.querySelectorAll('.stab-panel').forEach(p => p.classList.toggle('active', p.id === 'stab-' + tab));
}

svg.script:
(() => {
  const SVG_NS = "http://www.w3.org/2000/svg";
  const XLINK_NS = "http://www.w3.org/1999/xlink";
  const allowed = new Set(["", "text/javascript", "application/javascript", "text/ecmascript", "application/ecmascript", "module"]);
  const sources = [...document.querySelectorAll('script[type="application/x-svg-source-script"]')];

  function run(source) {
    return new Promise((done) => {
      const originalType = source.getAttribute("data-original-type") || "";
      if (!allowed.has(originalType.trim().toLowerCase())) return done();

      const script = document.createElementNS(SVG_NS, "script");
      const src = source.getAttribute("data-script-src");
      if (originalType) script.setAttribute("type", originalType);

      if (src) {
        script.setAttribute("href", src);
        script.setAttributeNS(XLINK_NS, "xlink:href", src);
        script.addEventListener("load", done, { once: true });
        script.addEventListener("error", done, { once: true });
        document.documentElement.appendChild(script);
        if (source.hasAttribute("data-async")) done();
      } else {
        script.textContent = source.textContent || "";
        document.documentElement.appendChild(script);
        done();
      }
    });
  }

  (async () => {
    for (const source of sources) await run(source);
    document.documentElement.setAttribute("data-scripts-replayed", "true");
  })().catch(console.error);
})();
